// Funciones globales requeridas
function clog() { console.log.apply(console, arguments); }


let client = null;
let default_settings = {}; 
let server = null;
let port = null;

document.addEventListener('DOMContentLoaded', function() {
	client = new XpraClient('screen');
	client.host = 'localhost';
	client.port = 10000;
	client.encoding = 'jpeg';

	client.capture_keyboard = true;

	client.init(false);
	client.connect();
})
